// Tests for engine.js.
//   node --test tests/test_engine.js
// The reference paths come from the R simulate() in the ECON 202 slides (slides/neoclassical_slides.qmd in the macro_principles repo),
// regenerated by: Rscript tests/fixtures/policy_universes_ref.R
const test = require('node:test');
const assert = require('node:assert');
const path = require('node:path');
const E = require(path.join(__dirname, '../engine.js'));
const REF = require('./fixtures/policy_universes_ref.json');

// The R loop, rebuilt from engine primitives.
function slidesSimulate(lambda, policyAt) {
  let ad = 1400, sras = 0;
  const y = [], p = [];
  for (let t = 0; t <= 24; t++) {
    if (t === 2) ad = 700;
    if (policyAt != null && t === policyAt) ad = 1400;
    const e = E.equilibrium(ad, sras, 0);
    y.push(e.y); p.push(e.p);
    sras -= lambda * (e.y - 9500);
  }
  return { y, p };
}

test('equilibrium matches the R slides paths (slides calibration)', () => {
  E.useCurves('slides');
  try {
  for (const c of REF) {
    const at = typeof c.policy_at === 'number' ? c.policy_at : null;
    const s = slidesSimulate(c.lambda, at);
    for (let t = 0; t < c.y.length; t++) {
      assert.ok(Math.abs(s.y[t] - c.y[t]) < 0.01, `lambda ${c.lambda} policy ${at} t ${t} y ${s.y[t]} vs ${c.y[t]}`);
      assert.ok(Math.abs(s.p[t] - c.p[t]) < 0.001, `lambda ${c.lambda} policy ${at} t ${t} p`);
    }
  }
  } finally { E.useCurves('game'); }
});

test('flexible stimulus ends at price 104 vs 90 with no policy (slides calibration)', () => {
  E.useCurves('slides');
  try {
  const none = REF.find(c => c.lambda === 1.5 && typeof c.policy_at !== 'number');
  const soon = REF.find(c => c.lambda === 1.5 && c.policy_at === 4);
  assert.ok(!none || true);
  const n = slidesSimulate(1.5, null), s = slidesSimulate(1.5, 4);
  assert.strictEqual(Math.round(n.p[24]), 90);
  assert.strictEqual(Math.round(s.p[24]), 104);
  if (soon) assert.ok(Math.abs(s.p[24] - soon.p[24]) < 0.001);
  } finally { E.useCurves('game'); }
});

test('starting point is potential 9,500 at price 104, unemployment 5, inflation 2', () => {
  const g = E.createGame({ universes: { a: E.PRESETS.keynesian, b: E.PRESETS.neoclassical } });
  for (const k of ['a', 'b']) {
    const r = g.universes[k].history[0];
    assert.ok(Math.abs(r.y - 9500) < 1e-6);
    assert.ok(Math.abs(r.p - 104) < 1e-6);
    assert.ok(Math.abs(r.unemployment - 5) < 1e-9);
    assert.strictEqual(r.inflation, 2);
  }
});

test('no shock and no policy keeps both universes at potential with full points', () => {
  const g = E.createGame({ rounds: 5, shockMode: 'custom', universes: { a: E.PRESETS.keynesian, b: E.PRESETS.neoclassical } });
  while (!g.isOver()) {
    const out = g.step({ shock: 'none' });
    for (const k of ['a', 'b']) {
      assert.ok(Math.abs(out[k].gap) < 1e-6);
      assert.strictEqual(out[k].points, 10);
    }
  }
});

test('a fully expected stimulus moves the price level, not output', () => {
  const s = Object.assign({}, E.PRESETS.neoclassical, { fiscalLag: 0, lambda: 0 });
  const u = new E.Universe(s);
  const r = u.step(1, 'none', 3, 0);
  assert.ok(Math.abs(r.y - 9500) < 1e-6, `y ${r.y}`);
  assert.ok(r.p > 104 + 1);
});

test('an unexpected stimulus raises output, by more with a bigger multiplier', () => {
  const base = Object.assign({}, E.PRESETS.keynesian, { fiscalLag: 0, lambda: 0, expected: 0 });
  const one = new E.Universe(Object.assign({}, base, { multiplier: 1 })).step(1, 'none', 2, 0);
  const two = new E.Universe(Object.assign({}, base, { multiplier: 2 })).step(1, 'none', 2, 0);
  assert.ok(one.y > 9500);
  assert.ok(two.y > one.y);
});

test('policy arrives after the lag', () => {
  const s = Object.assign({}, E.PRESETS.keynesian, { fiscalLag: 2, lambda: 0 });
  const u = new E.Universe(s);
  assert.strictEqual(u.step(1, 'none', 2, 0).policyArrived, false);
  assert.strictEqual(u.step(2, 'none', 0, 0).policyArrived, false);
  const r = u.step(3, 'none', 0, 0);
  assert.strictEqual(r.policyArrived, true);
  assert.ok(r.y > 9500);
});

test('sticky wages recover slower than flexible wages after demand falls', () => {
  const g = E.createGame({ rounds: 10, universes: { k: E.PRESETS.keynesian, n: E.PRESETS.neoclassical } });
  while (!g.isOver()) g.step({});
  const k = g.universes.k.history, n = g.universes.n.history;
  assert.strictEqual(k[2].shock, 'demand_drop');
  assert.ok(k[2].gap < -100 && n[2].gap < -100);
  assert.ok(Math.abs(n[4].gap) < Math.abs(k[4].gap));
  const sum = g.summary();
  assert.ok(sum.k.lostOutput > sum.n.lostOutput);
});

test('supply investment raises potential after the delay and costs points now', () => {
  const u = new E.Universe(E.PRESETS.neoclassical);
  const r1 = u.step(1, 'none', 0, 2);
  assert.strictEqual(r1.points, 10 - 2 * 2);
  u.step(2, 'none', 0, 0); u.step(3, 'none', 0, 0);
  const r4 = u.step(4, 'none', 0, 0);
  assert.strictEqual(r4.potential, 9500 + 2 * E.SUPPLY_GAIN);
});

test('real world switches lambda at the switch round', () => {
  const s = E.PRESETS.realworld;
  assert.strictEqual(E.lambdaAt(s, s.switchRound - 1), s.lambda);
  assert.strictEqual(E.lambdaAt(s, s.switchRound), s.lambdaLate);
});

test('the game ends after its rounds', () => {
  const g = E.createGame({ rounds: 4, universes: { a: E.PRESETS.keynesian } });
  for (let i = 0; i < 4; i++) g.step({});
  assert.ok(g.isOver());
  assert.throws(() => g.step({}));
});

test('welfare: after a demand drop, stimulus helps the Keynesian universe far more than the neoclassical one', () => {
  const g = E.createGame({ rounds: 12, shockMode: 'event', event: 'demand_drop', universes: { k: E.PRESETS.keynesian, n: E.PRESETS.neoclassical } });
  const plan = { 2: { spending: 3, rate: -0.5 } };
  while (!g.isOver()) g.step(plan[g.round + 1] || {});
  const s = g.summary();
  assert.ok(s.k.welfare > 50 && s.k.won, `Keynesian welfare ${s.k.welfare}`);
  assert.ok(s.k.welfare > s.n.welfare + 30, `Keynesian ${s.k.welfare} vs neoclassical ${s.n.welfare}`);
});

test('welfare: the wrong policy scores below zero, and the loss is quadratic', () => {
  const g = E.createGame({ rounds: 12, shockMode: 'event', event: 'boom', universes: { k: E.PRESETS.keynesian } });
  const plan = { 2: { spending: 3, rate: -0.5 } };
  while (!g.isOver()) g.step(plan[g.round + 1] || {});
  const s = g.summary().k;
  assert.ok(s.welfare < 0 && s.won === false, `stimulus in a boom: welfare ${s.welfare}`);
  const r = g.universes.k.history[3], sc = E.scoringOf();
  assert.ok(Math.abs(r.loss - (sc.wU * (r.unemployment - 5) ** 2 + sc.wPi * (r.inflation - 2) ** 2)) < 1e-9);
});

test('welfare: a tiny no-policy loss gives no percent, only the change in loss', () => {
  assert.strictEqual(E.welfareOf(0.1, 0.2), null);
  assert.strictEqual(E.welfareOf(5, 10), 50);
});

test('stacked cuts and extreme settings stay finite, on SRAS, and tightening lowers prices', () => {
  const g = E.createGame({ universes: { n: E.PRESETS.neoclassical } });
  const choices = { 1: { demand: -4 }, 2: { demand: -4 } };
  while (!g.isOver()) g.step(choices[g.round + 1] || {});
  const h = g.universes.n.history;
  assert.ok(h[3].p < h[2].p, `price ${h[3].p} after a cut should be below ${h[2].p}`);
  const shocks = Object.keys(E.SHOCKS);
  for (const lambda of [0, 1.5]) for (const multiplier of [1, 4]) for (const lag of [0, 3]) for (const d of [-4, 4]) {
    const s = Object.assign({}, E.PRESETS.keynesian, { lambda, multiplier, fiscalLag: lag, monetaryLag: lag, expected: 0.5 });
    const x = E.createGame({ rounds: 20, shockMode: 'custom', universes: { a: s } });
    let i = 0;
    while (!x.isOver()) {
      const r = x.step({ demand: d, supply: 3, shock: shocks[i++ % shocks.length] }).a;
      assert.ok(Number.isFinite(r.y) && Number.isFinite(r.p));
      assert.ok(Math.abs((r.nom || 1) * E.srasP(r.y, r.sras, r.lras) - r.p) < 1e-3, 'equilibrium off SRAS');
      assert.ok(r.p > 0);
    }
  }
});

test('a rate cut and a tax cut raise output; monetary has its own lag', () => {
  const s = Object.assign({}, E.PRESETS.keynesian, { lambda: 0, fiscalLag: 2, monetaryLag: 0 });
  const g = E.createGame({ rounds: 4, shockMode: 'custom', universes: { k: s } });
  const r1 = g.step({ rate: -1 }).k;
  assert.ok(r1.monetaryArrived && !r1.fiscalArrived);
  assert.ok(r1.y > 9500);
  assert.strictEqual(r1.rateLevel, E.START_RATE - 1);
  const t = new E.Universe(Object.assign({}, s, { fiscalLag: 0 })).step(1, 'none', { taxes: -2 });
  const sp = new E.Universe(Object.assign({}, s, { fiscalLag: 0 })).step(1, 'none', { spending: 2 });
  assert.ok(t.y > 9500 && t.y < sp.y, 'a tax cut moves output less than the same spending rise');
});

test('the interest rate stays between 0 and the maximum', () => {
  const g = E.createGame({ rounds: 6, shockMode: 'custom', universes: { k: E.PRESETS.keynesian } });
  for (let i = 0; i < 3; i++) g.step({ rate: -2 });
  assert.strictEqual(g.rate, 0);
  assert.strictEqual(g.universes.k.history[3].rate, 0);
});

test('event mode: the event hits in round 1 only, and stars and the win follow the green zone', () => {
  const g = E.createGame({ rounds: 8, shockMode: 'event', event: 'oil', universes: { n: E.PRESETS.neoclassical } });
  const r1 = g.step({}).n;
  assert.strictEqual(r1.shock, 'oil');
  assert.strictEqual(g.step({}).n.shock, 'none');
  while (!g.isOver()) g.step({});
  const h = g.universes.n.history;
  for (const r of h.slice(1)) {
    assert.strictEqual(r.stars, (r.inZone.unemployment ? 1 : 0) + (r.inZone.inflation ? 1 : 0));
  }
  const s = g.summary().n;
  assert.strictEqual(s.maxStars, 16);
  // Playing no policy (no fiscal steps, the real rate held at neutral) is
  // exactly the no-policy path, so no welfare gained and no win.
  const g2 = E.createGame({ rounds: 8, shockMode: 'event', event: 'oil', autopilot: { monetary: 'neutral' }, universes: { n: E.PRESETS.neoclassical } });
  while (!g2.isOver()) g2.step({});
  const s2 = g2.summary().n;
  assert.strictEqual(s2.loss, s2.lossNoPolicy);
  assert.strictEqual(s2.won, false);
});

test('a productivity gain lifts AD by half the gain', () => {
  const u = new E.Universe(E.PRESETS.keynesian);
  const ad0 = u.ad;
  u.step(1, 'productivity', {});
  assert.strictEqual(u.ad, ad0 + E.GROWTH_AD_SHARE * E.SHOCKS.productivity.lras);
});

test('credibility: with adaptive expectations oil-shock inflation sticks; a credible bank brings it back', () => {
  const play = (credibility) => {
    const s = Object.assign({}, E.PRESETS.keynesian, { credibility });
    const g = E.createGame({ rounds: 6, shockMode: 'event', event: 'oil', universes: { k: s } });
    while (!g.isOver()) g.step({});
    return g.universes.k.history.map(r => r.inflation);
  };
  const adaptive = play(0), credible = play(0.9);
  assert.ok(adaptive[6] > 5, `adaptive: inflation ${adaptive[6]} should stay high with the rate held`);
  assert.ok(Math.abs(credible[6] - 2) < 1, `credible: inflation ${credible[6]} should return near 2%`);
});

test('the real-rate channel: holding the nominal rate while expected inflation rises lowers the real rate', () => {
  const g = E.createGame({ rounds: 3, shockMode: 'event', event: 'boom', universes: { k: E.PRESETS.keynesian } });
  g.step({}); g.step({}); g.step({});
  const h = g.universes.k.history;
  assert.ok(h[3].expectedInflation > 2 && h[3].realRate < E.R_STAR, `real rate ${h[3].realRate}`);
  assert.strictEqual(h[3].nominalRate, E.START_RATE);
});

test('scoring: bands, weights and off', () => {
  const play = (scoring) => {
    const g = E.createGame({ rounds: 4, shockMode: 'event', event: 'demand_drop', scoring, universes: { k: E.PRESETS.neoclassical } });
    while (!g.isOver()) g.step({});
    return g.summary().k;
  };
  const off = play({ on: false });
  assert.strictEqual(off.stars, 0); assert.strictEqual(off.won, null);
  const wide = play({ uBand: 2, piBand: 3 }), narrow = play({ uBand: 0.25, piBand: 0.5 });
  assert.ok(wide.stars >= narrow.stars);
  const onlyU = play({ wU: 2, wPi: 0 });
  assert.strictEqual(onlyU.maxStars, 8);
});

test('a rate hike brings persistent inflation down faster', () => {
  const play = (plan) => {
    const g = E.createGame({ rounds: 5, shockMode: 'event', event: 'boom', universes: { k: E.PRESETS.keynesian } });
    while (!g.isOver()) g.step(plan[g.round + 1] || {});
    return g.universes.k.history[4].inflation;
  };
  assert.ok(play({ 2: { rate: 0.5 } }) < play({}));
});

test('a 25 basis point move is a nudge, not a jolt', () => {
  const s = Object.assign({}, E.PRESETS.keynesian, { monetaryLag: 0, lambda: 0, inertia: 0 });
  const g = E.createGame({ rounds: 3, shockMode: 'custom', universes: { k: s } });
  const r = g.step({ rate: 0.25 }).k;
  assert.ok(Math.abs(r.inflation - 2) < 0.5, `inflation ${r.inflation}`);
  assert.ok(Math.abs(r.unemployment - 5) < 0.2, `unemployment ${r.unemployment}`);
});

test('Taylor autopilot: steady, and it leans against a boom', () => {
  const g = E.createGame({ rounds: 8, shockMode: 'event', event: 'oil', autopilot: { monetary: true }, universes: { k: E.PRESETS.keynesian } });
  while (!g.isOver()) g.step({});
  const rates = g.universes.k.history.slice(1).map(r => r.rateLevel);
  for (let i = 1; i < rates.length; i++) assert.ok(Math.abs(rates[i] - rates[i - 1]) <= 3.5, `rate jumped ${rates[i - 1]} to ${rates[i]}`);
  assert.ok(Math.max(...rates) > 3, 'it should raise rates against oil-shock inflation');
  assert.ok(g.universes.k.history.every(r => r.autoRate || r.round === 0));
});

test('balanced-budget autopilot cuts spending in a slump and deepens it', () => {
  const play = (ap) => {
    const g = E.createGame({ rounds: 6, shockMode: 'event', event: 'demand_drop', autopilot: ap, universes: { k: E.PRESETS.keynesian } });
    while (!g.isOver()) g.step({ spending: 3 });
    return g.universes.k.history;
  };
  const bb = play({ fiscal: true }), none = play({});
  assert.ok(bb.some(r => r.autoSpending < 0), 'spending should be cut after GDP falls');
  assert.ok(bb.every(r => r.spending === 0), 'the fiscal levers are ignored on autopilot');
  assert.ok(bb[6].unemployment > none[6].unemployment);
});

test('the no-policy twin gets the same event, no fiscal steps, and the real rate held at neutral', () => {
  const g = E.createGame({ rounds: 4, shockMode: 'event', event: 'demand_drop', universes: { k: E.PRESETS.keynesian } });
  g.step({}); g.step({ spending: 4, rate: -2 }); g.step({}); g.step({});
  const np = g.noPolicy('k');
  assert.strictEqual(np.length, 5);
  assert.strictEqual(np[1].shock, 'demand_drop');
  assert.ok(np.every(r => r.spending === 0 && r.taxes === 0));
  // Each round the rate is set, in 25 basis point steps, to expected inflation
  // plus the neutral real rate of 1% (at 0 or above).
  for (let i = 1; i < np.length; i++) {
    const target = Math.max(0, np[i - 1].expectedNext != null ? np[i - 1].expectedNext + E.R_STAR : E.START_RATE);
    assert.strictEqual(np[i].autoRateMode, 'neutral');
    assert.ok(Math.abs(np[i].rateLevel - target) <= 0.125 + 1e-9, `round ${i}: ${np[i].rateLevel} vs ${target}`);
  }
  assert.ok(g.universes.k.history[4].y > np[4].y, 'the stimulus should beat doing nothing');
});

test('holding the nominal rate is a policy: in a Keynesian boom it lets the real rate fall', () => {
  const play = (ap) => {
    const g = E.createGame({ rounds: 8, shockMode: 'event', event: 'boom', noBaseline: true, autopilot: ap, universes: { k: E.PRESETS.keynesian } });
    while (!g.isOver()) g.step({});
    return g.universes.k.history;
  };
  const held = play({}), neutral = play({ monetary: 'neutral' });
  assert.ok(held[6].realRate < neutral[6].realRate, `real rate held ${held[6].realRate} vs neutral ${neutral[6].realRate}`);
  assert.ok(held[6].inflation > neutral[6].inflation);
});

test('direction helper', () => {
  assert.strictEqual(E.direction(5, 5.5), 'up');
  assert.strictEqual(E.direction(5, 4.5), 'down');
  assert.strictEqual(E.direction(5, 5.1), 'same');
});

test('no lurches: 20 rounds of every preset and event, with and without the Taylor rule', () => {
  for (const pre of Object.keys(E.PRESETS)) for (const ev of E.EVENTS) for (const ap of [{}, { monetary: true }]) {
    const g = E.createGame({ rounds: 20, shockMode: 'event', event: ev, autopilot: ap, universes: { a: E.PRESETS[pre] } });
    while (!g.isOver()) g.step({});
    const h = g.universes.a.history;
    for (let i = 1; i < h.length; i++) {
      assert.ok(Number.isFinite(h[i].p) && h[i].p > 0, `${pre} ${ev} round ${i} price`);
      assert.ok(Math.abs(h[i].nom * E.srasP(h[i].y, h[i].sras, h[i].lras) - h[i].p) < 1e-3, `${pre} ${ev} round ${i} off SRAS`);
      if (i >= 3) assert.ok(Math.abs(h[i].inflation - h[i - 1].inflation) <= 3.5, `${pre} ${ev} ${ap.monetary ? 'Taylor' : 'none'} round ${i}: inflation jumped ${h[i - 1].inflation.toFixed(1)} to ${h[i].inflation.toFixed(1)}`);
    }
  }
});

test('autopilot can be switched on and off mid-game', () => {
  const g = E.createGame({ rounds: 6, shockMode: 'event', event: 'boom', universes: { k: E.PRESETS.keynesian } });
  g.step({}); g.step({ rate: 0.25 });
  g.autopilot.monetary = true;
  const r3 = g.step({ rate: -2 }).k;
  assert.ok(r3.autoRate, 'the Taylor rule sets round 3');
  assert.ok(r3.rate > 0, 'it ignores the manual cut and raises the rate against the boom');
  g.autopilot.monetary = false;
  const r4 = g.step({ rate: -0.5 }).k;
  assert.ok(!r4.autoRate && r4.rate === -0.5, 'manual control is back in round 4');
});

test('a cloned game plays identically and independently', () => {
  const g = E.createGame({ rounds: 10, shockMode: 'event', event: 'oil', universes: { k: E.PRESETS.keynesian, n: E.PRESETS.newkeynesian } });
  g.step({}); g.step({ spending: 2, rate: 0.5 }); g.step({ taxes: -1 });
  const c = g.clone();
  const plan = [{ rate: 0.25 }, {}, { spending: -1, rate: -0.5 }, {}, { rate: 1 }];
  for (const ch of plan) { g.step(ch); c.step(ch); }
  for (const k of ['k', 'n']) {
    assert.deepStrictEqual(c.universes[k].history.map(r => [r.y, r.p, r.inflation]), g.universes[k].history.map(r => [r.y, r.p, r.inflation]));
    assert.deepStrictEqual(c.noPolicy(k).map(r => r.y), g.noPolicy(k).map(r => r.y));
  }
  const before = g.universes.k.history.length;
  c.step({ rate: 2 });
  assert.strictEqual(g.universes.k.history.length, before, 'stepping the copy leaves the original alone');
  const longer = g.clone({ rounds: 14 });
  assert.strictEqual(longer.rounds, 14);
});

test('Taylor autopilot settles: no full-size swings late in a long game, any preset or event', () => {
  for (const pre of Object.keys(E.PRESETS)) for (const ev of E.EVENTS) {
    const g = E.createGame({ rounds: 40, shockMode: 'event', event: ev, noBaseline: true, autopilot: { monetary: 'taylor' }, universes: { a: E.PRESETS[pre] } });
    while (!g.isOver()) g.step({});
    const late = g.universes.a.history.slice(29).filter(r => Math.abs(r.rate) >= 0.75).length;
    assert.ok(late < 3, `${pre} ${ev}: ${late} moves of 75 basis points or more in rounds 29 to 40`);
  }
});

test('no preset reaches a curve limit, with no policy or the Taylor rule, over 12, 20 or 40 rounds', () => {
  for (const pre of Object.keys(E.PRESETS)) for (const ev of E.EVENTS) for (const ap of [false, 'taylor']) for (const n of [12, 20, 40]) {
    const g = E.createGame({ rounds: n, shockMode: 'event', event: ev, autopilot: { monetary: ap }, universes: { a: E.PRESETS[pre] } });
    while (!g.isOver()) g.step({});
    assert.ok(!g.universes.a.history.some(r => r.atLimit) && !g.noPolicy('a').some(r => r.atLimit), `${pre} ${ev} ${ap || 'none'} ${n} rounds`);
  }
});

test('a path pushed past a curve limit is flagged', () => {
  const s = Object.assign({}, E.PRESETS.monetarist, { credibility: 0 });
  const g = E.createGame({ rounds: 40, shockMode: 'event', event: 'boom', noBaseline: true, universes: { a: s } });
  while (!g.isOver()) g.step({});
  assert.ok(g.universes.a.history.some(r => r.atLimit), 'adaptive expectations with the rate held should run into a limit');
});
